args.script:
(async () => {
  const at = Number(localStorage.getItem('abx_bearer_at') || 0);
  const cur = localStorage.getItem('abx_bearer') || '';
  const fresh = cur && at && (Date.now() - at) < 12 * 3600e3;
  if (fresh) return JSON.stringify({ok: true, src: 'cached', len: cur.length});
  const src = [...document.querySelectorAll("script[src*='main']")].map(s => s.src)[0];
  if (!src) return JSON.stringify({ok: !!cur, src: 'kept-no-main', len: cur.length});
  const t = await (await fetch(src, {credentials: 'omit'})).text();
  const m = t.match(/Bearer ([A-Za-z0-9%/+=]{80,})/);
  if (!m) return JSON.stringify({ok: !!cur, src: 'kept-no-match', len: cur.length});
  localStorage.setItem('abx_bearer', m[1]);
  localStorage.setItem('abx_bearer_at', String(Date.now()));
  return JSON.stringify({ok: true, src: 'refreshed', len: m[1].length});
})()

// x-notifs step: fetch v2 URT notifications (all/mentions tabs) and triage
(async () => {
  const ARGS = {{args_json}};
  try {
    const bearer = localStorage.getItem('abx_bearer');
    const ct0 = (document.cookie.match(/(?:^|;\s*)ct0=([^;]+)/) || [])[1];
    if (!bearer || !ct0) return JSON.stringify({ok: false, err: 'missing bearer/ct0 - session not logged in'});
    const KIND = {person_icon: 'follow', heart_icon: 'like', retweet_icon: 'retweet', reply_icon: 'reply',
                  mention_icon: 'mention', favorite_icon: 'like', list_icon: 'list', rocket_icon: 'followed_tweet'};
    const tab = ARGS.tab || 'all';
    const q = '/i/api/2/notifications/' + tab + '.json?count=' + (ARGS.count || 40) +
      '&requestContext=launch&pc=1&spelling_corrections=0&include_ext_is_blue_verified=1&include_ext_verified_type=1' +
      '&include_reply_count=1&include_ext_views=true&tweet_mode=extended&include_entities=true&include_user_entities=true';
    const r = await fetch(q, {credentials: 'include', headers: {
      'authorization': 'Bearer ' + bearer,
      'x-twitter-auth-type': 'OAuth2Session',
      'x-csrf-token': ct0,
      'x-twitter-client-language': 'en',
      'x-twitter-active-user': 'yes'}});
    const t = await r.text();
    let j = null; try { j = JSON.parse(t); } catch {}
    if (!r.ok) return JSON.stringify({ok: false, status: r.status, err_head: t.slice(0, 120)});
    const go = j.globalObjects || {};
    const users = go.users || {};
    const u = (id) => { const x = users[id] || {}; return {sn: x.screen_name, name: x.name, fol: x.followers_count, blue: !!x.ext_is_blue_verified}; };
    const rows = Object.values(go.notifications || {}).map(m => {
      const tpl = m.template || {};
      const agg = tpl.aggregateUserActionsV1 || {};
      const fromIds = (agg.fromUsers || []).map(x => x.user && x.user.id).filter(Boolean);
      const tweetRef = (m.message && m.message.entities || []).map(e => e.ref && e.ref.tweet && e.ref.tweet.id).filter(Boolean)[0] || null;
      return {
        kind: KIND[(m.icon || {}).id] || ((m.icon || {}).id || 'unknown'),
        text: (m.message && m.message.text || '').slice(0, 140),
        from: fromIds.length === 1 ? u(fromIds[0]) : fromIds.map(u),
        from_n: fromIds.length,
        tweet_id: tweetRef,
        ts: Number(m.timestampMs || 0)
      };
    }).sort((a, b) => b.ts - a.ts);
    const counts = {};
    for (const x of rows) counts[x.kind] = (counts[x.kind] || 0) + 1;
    // actionable = mentions/replies (someone talking to us); social = like/retweet/follow
    const actionable = rows.filter(x => x.kind === 'mention' || x.kind === 'reply');
    return JSON.stringify({ok: true, status: r.status, tab, n: rows.length, counts,
      actionable_n: actionable.length, items: rows.slice(0, ARGS.top || 20)});
  } catch (e) {
    return JSON.stringify({ok: false, err: e.name + ': ' + e.message});
  }
})()
